/* =====================================================================
   HEALTHCARE DATA LOADER (PostgreSQL)  -  run this whole file ONCE
   It creates the table "healthcare" and inserts all 54,860 cleaned rows.
   (Exact duplicates and negative bills are already removed.)
   No CSV import or psql commands needed.
   After it finishes, open 02_healthcare_queries.sql and run the queries.
   ===================================================================== */

DROP TABLE IF EXISTS healthcare;

CREATE TABLE healthcare (
    admission_id        SERIAL PRIMARY KEY,
    name                TEXT,
    age                 INTEGER,
    gender              TEXT,
    blood_type          TEXT,
    medical_condition   TEXT,
    date_of_admission   DATE,
    doctor              TEXT,
    hospital            TEXT,
    insurance_provider  TEXT,
    billing_amount      NUMERIC(12,2),
    room_number         INTEGER,
    admission_type      TEXT,
    discharge_date      DATE,
    medication          TEXT,
    test_results        TEXT,
    length_of_stay      INTEGER,
    admission_year      INTEGER,
    admission_month     TEXT
);















































































































CREATE INDEX idx_hc_condition ON healthcare (medical_condition);
CREATE INDEX idx_hc_admtype   ON healthcare (admission_type);
CREATE INDEX idx_hc_insurer   ON healthcare (insurance_provider);

-- Check: should return 54860
SELECT COUNT(*) AS rows_in_healthcare FROM healthcare;
